u64 get_netlink_attr_offset(u64 ctx, u64 A, u64 X, u64 r4, u64 r5) {
    // Assume helper functions and types such as skb_is_nonlinear(), skb_len(), and NLMSG_ATTR_HDRLEN
    // are defined elsewhere in the codebase or provided by the headers included.
    u64 skb_data = get_skb_data(ctx); // Assuming a helper to get start of socket buffer data
    u64 skb_data_len = skb_len(ctx); // Assuming a helper to get socket buffer length

    if (skb_is_nonlinear(ctx) || skb_data_len < NLMSG_ATTR_HDRLEN) {
        return 0;
    }

    if (A >= skb_data_len) {
        return 0;
    }

    u64 start_pos = skb_data + A;
    u64 end_pos = skb_data + skb_data_len;
    u64 current_pos = start_pos;

    while (current_pos + NLMSG_ATTR_HDRLEN <= end_pos) {
        u64 attr_type = *(u32 *)current_pos;
        if (attr_type == X) {
            return current_pos - skb_data;
        }
        u64 attr_len = *(u32 *)(current_pos + 4);
        if (attr_len < NLMSG_ATTR_HDRLEN || current_pos + attr_len > end_pos) {
            return 0;
        }
        current_pos += attr_len;
    }

    return 0;
}

u64 get_netlink_attr_offset(u64 ctx, u64 A, u64 X, u64 r4, u64 r5) {
    struct sk_buff *skb = (struct sk_buff *)(long)ctx;
    struct nlattr *nla;

    // Check if the socket buffer is non-linear or if its length is less than the size of a netlink attribute
    if (!skb || skb_is_nonlinear(skb) || skb->len < NLA_HDRLEN)
        return 0;

    // Verify that the provided offset A is valid
    if (A >= skb->len)
        return 0;

    // Search for the netlink attribute of type X starting from the calculated position
    nla = (struct nlattr *)((u8 *)skb->data + A);
    if (nla->nla_type == X) {
        return (u64)((u8 *)nla - (u8 *)skb->data);
    }

    return 0;
}

u64 get_netlink_attr_offset(u64 ctx, u64 A, u64 X, u64 r4, u64 r5) {
    struct sk_buff *skb = (struct sk_buff *)(ctx);
    struct nlattr *nla;
    int rem;

    if (!skb || skb->len < NLA_HDRLEN)
        return 0;

    if (A >= skb->len)
        return 0;

    nla_for_each_attr(nla, skb, skb->len, rem) {
        if (nla_type(nla) == X) {
            return (u64)((void *)nla - skb->data);
        }
        if (nla->nla_len < NLA_HDRLEN)
            break;
        A += nla->nla_len;
        if (A > skb->len)
            break;
    }

    return 0;
}

