u64 get_netlink_attr_offset(u64 ctx, u64 A, u64 X, u64 r4, u64 r5) {
    struct sk_buff *skb = (struct sk_buff *)ctx;
    u64 offset = 0;

    if (skb_is_nonlinear(skb) || skb->len < sizeof(struct nlattr)) {
        return 0;
    }

    if (A >= skb->len) {
        return 0;
    }

    struct nlattr *nla = (struct nlattr *)((char *)skb->data + A);
    int rem;
    nla_for_each_attr(nla, skb, skb->len - A, rem) {
        if (nla->nla_type == X) {
            offset = (u64)((char *)nla - (char *)skb->data);
            return offset;
        }
    }

